"""Cloud API, retry and credential boundaries. Generated bytes only, no personal login."""
import hashlib
import io
import json
import os
from pathlib import Path
import sys
import tempfile
import unittest
from unittest.mock import patch

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
import velcro_cloud as c
from velcro_credentials import Credentials, CredentialError


class MemoryCredentials:
    def __init__(self, token="bxd_" + "x" * 40):
        self.token = token

    def get(self):
        return self.token

    def set(self, token):
        self.token = token


class Worker:
    def __init__(self):
        self.parts, self.calls, self.received = {}, [], False
        self.fail_part, self.lose_complete, self.session = None, False, "session-1"
        self.id = "a" * 64

    def request(self, url, method="GET", data=None, headers=None):
        route = url.split(".test", 1)[1]
        self.calls.append((method, route))
        assert headers["Authorization"].startswith("Bearer bxd_")
        if route == "/v1/uploads":
            assert set(data) == {"size", "sha256", "ext", "recordedAt"}
            self.meta = data
            return {"id": self.id, "transport": "multipart", "uploadSession": self.session,
                    "partSize": 5, "partCount": (data["size"] + 4) // 5}
        if method == "GET":
            return {"id": self.id, "phase": "received" if self.received else "uploading"}
        assert headers["Upload-Session"] == self.session
        if "/parts/" in route:
            number = int(route.rsplit("/", 1)[1])
            if self.fail_part == number:
                self.fail_part = None
                raise c.CloudError("Cloud unavailable")
            assert headers["Content-Length"] == str(len(data))
            self.parts[number] = data
            return {"partNumber": number}
        raw = b"".join(self.parts[n] for n in sorted(self.parts))
        assert hashlib.sha256(raw).hexdigest() == self.meta["sha256"]
        self.received = True
        if self.lose_complete:
            self.lose_complete = False
            raise c.CloudError("Cloud unavailable")
        return {"phase": "received"}


class Upload(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.addCleanup(self.temp.cleanup)
        self.folder = Path(self.temp.name) / "backup"
        self.folder.mkdir()
        self.audio = self.folder / "silence.wav"
        self.audio.write_bytes(b"\0" * 12)
        self.record = {"file": self.audio.name, "size": 12, "sha256": hashlib.sha256(self.audio.read_bytes()).hexdigest(),
                       "imported_at": "2026-11-09T12:00:00+09:00", "device": "Test", "device_uuid": "",
                       "original": "silence.wav", "duration_s": None, "import": "test"}
        self.manifest = self.folder / c.MANIFEST
        self.manifest.write_text(json.dumps(self.record) + "\n")
        self.worker, self.credentials = Worker(), MemoryCredentials()
        self.clock = 1_000
        self.state = Path(self.temp.name) / "state"
        self.uploader = c.Uploader("https://cloud.test", self.state, self.credentials, self.worker.request, lambda: self.clock)
        self.log = []

    def run_upload(self):
        return self.uploader.run(self.folder, self.log.append)

    def test_verified_upload_preserves_backup_and_manifest_shape(self):
        self.assertEqual(self.run_upload(), 0)
        record = c.read_manifest(self.folder)[0]
        self.assertEqual(list(record)[:-1], list(self.record))
        self.assertEqual(record["cloud"]["id"], self.worker.id)
        self.assertEqual(record["cloud"]["status"], "uploaded")
        self.assertEqual(self.worker.meta["recordedAt"], "2026-11-09T03:00:00Z")
        self.assertEqual(self.audio.read_bytes(), b"\0" * 12)
        calls = len(self.worker.calls)
        self.assertEqual(self.run_upload(), 0)
        self.assertEqual(len(self.worker.calls), calls)

    def test_restart_resumes_confirmed_parts_and_backs_off(self):
        self.worker.fail_part = 2
        self.assertEqual(self.run_upload(), 1)
        mark = c.read_manifest(self.folder)[0]["cloud"]
        self.assertEqual(mark["id"], self.worker.id)
        self.assertEqual(mark["retry_at"], 1030)
        calls = len(self.worker.calls)
        self.run_upload()
        self.assertEqual(len(self.worker.calls), calls)
        self.clock = 1031
        self.uploader = c.Uploader("https://cloud.test", self.state, self.credentials, self.worker.request, lambda: self.clock)
        self.assertEqual(self.run_upload(), 0)
        self.assertEqual(self.worker.calls.count(("PUT", "/v1/uploads/" + self.worker.id + "/parts/1")), 1)

    def test_lost_completion_response_checks_remote_before_resending(self):
        self.worker.lose_complete = True
        self.assertEqual(self.run_upload(), 1)
        self.clock += 31
        self.assertEqual(self.run_upload(), 0)
        self.assertEqual(len([r for m, r in self.worker.calls if m == "PUT"]), 3)

    def test_new_upload_session_restarts_parts(self):
        self.worker.fail_part = 2
        self.run_upload()
        self.worker.session = "session-2"
        self.worker.parts = {}
        self.clock += 31
        self.assertEqual(self.run_upload(), 0)
        self.assertEqual(self.worker.calls.count(("PUT", "/v1/uploads/" + self.worker.id + "/parts/1")), 2)

    def test_other_login_does_not_reuse_prior_accounts_success(self):
        self.run_upload()
        self.credentials.token = "bxd_" + "y" * 40
        self.worker.received = False
        self.worker.parts = {}
        calls = len(self.worker.calls)
        self.assertEqual(self.run_upload(), 0)
        self.assertGreater(len(self.worker.calls), calls)

    def test_changed_backup_is_not_sent(self):
        self.audio.write_bytes(b"changed")
        self.assertEqual(self.run_upload(), 1)
        self.assertFalse(self.worker.calls)
        self.assertTrue(self.audio.exists())

    def test_parent_path_and_symlink_are_never_uploaded(self):
        for name in ("../private.wav", "/private.wav"):
            with self.assertRaises(c.CloudError):
                self.uploader.upload(self.folder, {**self.record, "file": name})
        link = self.folder / "link.wav"
        link.symlink_to(self.audio)
        with self.assertRaises(c.CloudError):
            self.uploader.upload(self.folder, {**self.record, "file": link.name})
        self.assertFalse(self.worker.calls)

    def test_token_is_not_written_to_checkpoint_manifest_or_log(self):
        self.run_upload()
        stored = self.manifest.read_text() + "".join(p.read_text() for p in self.state.iterdir()) + str(self.log)
        self.assertNotIn(self.credentials.token, stored)
        if os.name != "nt":
            self.assertEqual(next(self.state.iterdir()).stat().st_mode & 0o777, 0o600)

    def test_cloud_http_error_never_exposes_response_details(self):
        import urllib.error
        error = urllib.error.HTTPError("https://cloud.test/private", 401, "bxd_private_secret", {}, io.BytesIO())
        self.addCleanup(error.close)
        with patch("urllib.request.OpenerDirector.open", side_effect=error):
            with self.assertRaises(c.CloudError) as raised:
                c.request("https://cloud.test")
        self.assertEqual(str(raised.exception), "Cloud request failed (HTTP 401)")

    def test_cloud_redirect_is_refused(self):
        self.assertIsNone(c.NoRedirect().redirect_request(None, None, 302, "", {}, "https://elsewhere.test"))

    def test_filename_reuse_does_not_restore_old_hash_or_import(self):
        self.audio.write_bytes(b"new recording")
        new = {**self.record, "size": self.audio.stat().st_size,
               "sha256": hashlib.sha256(self.audio.read_bytes()).hexdigest(), "import": "new-import"}
        with self.manifest.open("a") as f:
            f.write(json.dumps(new) + "\n")
        self.assertEqual(self.run_upload(), 0)
        c.cloud_mark(self.folder, self.record, {"status": "pending"})
        self.assertEqual(c.read_manifest(self.folder)[0]["import"], "new-import")
        self.assertEqual(json.loads(self.manifest.read_text().splitlines()[-1])["sha256"], new["sha256"])

    def test_other_importers_appends_survive_status_updates(self):
        other = {**self.record, "file": "other.wav"}
        with self.manifest.open("a") as f:
            f.write(json.dumps(other) + "\n")
        c.cloud_mark(self.folder, self.record, {"status": "pending"})
        self.assertEqual({r["file"] for r in c.read_manifest(self.folder)}, {"silence.wav", "other.wav"})
        self.assertTrue(self.manifest.read_text().startswith(json.dumps(self.record) + "\n"))

    def test_concurrent_new_import_wins_over_a_late_old_status(self):
        snapshot = c.read_manifest(self.folder)
        new = {**self.record, "sha256": "b" * 64, "import": "new-import"}

        def racing_read(folder):
            with self.manifest.open("a") as f:
                f.write(json.dumps(new) + "\n")
            return snapshot

        with patch.object(c, "read_manifest", side_effect=racing_read):
            c.cloud_mark(self.folder, self.record, {"status": "pending"})
        actual = c.read_manifest(self.folder)[0]
        self.assertEqual(actual["import"], "new-import")
        self.assertNotIn("cloud", actual)


class Login(unittest.TestCase):
    def test_device_login_stores_only_in_credential_store(self):
        store, messages = MemoryCredentials(""), []
        secret = "bxd_" + "s" * 40
        replies = [{"deviceAuthorizationEndpoint": "https://auth.test/api/device/code", "tokenEndpoint": "https://auth.test/api/device/token"},
                   {"verify_url": "https://auth.test/device?code=ABCD", "device_code": "private-code", "expires_in": 600, "interval": 3},
                   {"state": "pending"}, {"state": "approved", "token": secret}]
        with patch.object(c, "request", side_effect=replies) as request, patch.object(c.time, "sleep"):
            c.login("https://cloud.test", store, messages.append, lambda u: None)
        self.assertEqual(store.get(), secret)
        self.assertNotIn(secret, str(messages))
        self.assertNotIn("private-code", str(messages))
        self.assertEqual(request.call_args_list[1].args[2]["tools"], ["velcro"])

    def test_denied_login_never_saves_token(self):
        store = MemoryCredentials("")
        replies = [{"deviceAuthorizationEndpoint": "https://auth.test/api/device/code", "tokenEndpoint": "https://auth.test/api/device/token"},
                   {"verify_url": "https://auth.test/device?code=ABCD", "device_code": "private-code", "expires_in": 600},
                   c.CloudError("denied", 403)]
        with patch.object(c, "request", side_effect=replies), patch.object(c.time, "sleep"):
            with self.assertRaises(c.CloudError):
                c.login("https://cloud.test", store, lambda _: None, lambda _: None)
        self.assertFalse(store.get())

    def test_insecure_server_addresses_are_refused(self):
        for url in ("http://cloud.test", "https://u:password@cloud.test", "https://cloud.test/path", "https://cloud.test?key=secret"):
            with self.assertRaises(c.CloudError):
                c.cloud_url(url)

    def test_linux_has_no_plaintext_credential_fallback(self):
        with patch("velcro_credentials.sys.platform", "linux"):
            with self.assertRaises(CredentialError):
                Credentials("https://cloud.test").set("secret")


if __name__ == "__main__":
    unittest.main()
